	upper, lower := 0, 0
	for i := 0; i < len(word); i++ {
		if word[i] >= 'a' && word[i] <= 'z' {
			lower++
		} else {
			upper++
		}
	}
	return upper == len(word) || lower == len(word) || (upper == 1 && word[0] >= 'A' && word[0] <= 'Z')
}

class Solution {
  public boolean detectCapitalUse(String word) {
    int upper = 0, lower = 0;
    for (int i = 0; i < word.length(); i++) {
      if (Character.isLowerCase(word.charAt(i))) {
        lower++;
      } else {
        upper++;
      }
    }
    return upper == word.length() || lower == word.length()
        || (upper == 1 && Character.isUpperCase(word.charAt(0)));
  }
}

class Solution:
    def detectCapitalUse(self, word: str) -> bool:
        upper = sum(1 for c in word if c.isupper())
        lower = len(word) - upper
        return upper == len(word) or lower == len(word) or (upper == 1 and word[0].isupper())

impl Solution {
  pub fn detect_capital_use(word: String) -> bool {
    let b = word.as_bytes();
    let upper = b.iter().filter(|&&c| c.is_ascii_uppercase()).count();
    let lower = b.len() - upper;
    upper == b.len() || lower == b.len() || (upper == 1 && b[0].is_ascii_uppercase())
  }
}

const detectCapitalUse = (word: string): boolean => {
  let upper = 0;
  for (const c of word) if (c >= 'A' && c <= 'Z') upper++;
  const lower = word.length - upper;
  return (
    upper === word.length ||
    lower === word.length ||
    (upper === 1 && word[0] >= 'A' && word[0] <= 'Z')
  );
};
